import {primaryChannel,metricValue} from './channel-metrics.js';
import {SOCIAL_CONFIG} from './social-heat.js';
export const MAP_CONFIG={labelZoom:14,chainMinimum:3,upcomingStages:['announced','planning','construction','preopening','partially_open'],starColor:'#ffd329',bands:[{min:200,label:'200+ · Very high',color:'#da4037'},{min:100,label:'100–199 · High',color:'#f28a34'},{min:50,label:'50–99 · Medium',color:'#279766'},{min:0,label:'Under 50 · Lower',color:'#a4d7b6'}],unknown:{label:'Insufficient data / status unconfirmed',color:'#87919c'}};
const normalize=s=>String(s||'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
function brandKey(r){if(r.chain?.brand)return normalize(r.chain.brand);const name=r.name?.split(/\s+[—–]\s+/)[0];return /^(unnamed|unresolved|unknown)/i.test(name||'')?'':normalize(name);}
export function chainInfo(r,records){const key=brandKey(r);if(!key)return {isChain:false,count:0};const sites=new Set(records.filter(x=>x.phase!=='closed'&&brandKey(x)===key).map(x=>x.placeId||normalize((x.address||'')+' '+(x.suburb||''))||x.id));return {isChain:sites.size>=MAP_CONFIG.chainMinimum,count:sites.size};}
export function socialReach(r,records){const base=records.find(x=>x.id===SOCIAL_CONFIG.benchmarkId),components=[];if(!base)return {score:null,components,shared:false};for(const [platform,key]of [['Instagram','followers'],['Facebook','page_likes']]){const c=primaryChannel(r,platform),b=primaryChannel(base,platform),v=metricValue(c,key),bv=metricValue(b,key);if(!v||!bv||bv.value<=0||c.checked?.slice(0,10)!==b.checked?.slice(0,10))continue;components.push({platform,key,value:v.value,reference:bv.value,ratio:v.value/bv.value,shared:c.scope==='shared_account',source:c.url});}return {score:components.length?Math.round(100*components.reduce((n,c)=>n+c.ratio,0)/components.length):null,components,shared:components.some(c=>c.shared)};}
export function markerAppearance(r,records){const chain=chainInfo(r,records),reach=socialReach(r,records),upcoming=MAP_CONFIG.upcomingStages.includes(r.phase),band=reach.score===null?MAP_CONFIG.unknown:MAP_CONFIG.bands.find(b=>reach.score>=b.min);return {shape:upcoming?'star':chain.isChain?'square':'circle',color:upcoming?MAP_CONFIG.starColor:r.phase==='open'?band.color:MAP_CONFIG.unknown.color,chain,reach,upcoming,label:upcoming?(r.phase==='partially_open'?'Play area not fully open':'Not yet open'):r.phase==='open'?(reach.score===null?'Social reach: insufficient data':`Social reach: ${reach.score}${reach.shared?' · Shared brand account':''}`):'Opening status unconfirmed / closed'};}
